    "Độ sáng video đang cao và lớp phủ tối rất thấp — nên kéo \"Độ tối phủ nền\" lên 20%–40% để chữ luôn dễ đọc.": "影片亮度較高且暗色遮罩過低——建議將「背景暗化遮罩」調至 20%–40% 以保證文字清晰易讀。",
