    "# HỒ SƠ KHUNG STORY BIBLE — THỂ LOẠI TRINH THÁM NOIR / BÍ ẨN": "# 設定集結構框架 (STORY BIBLE) — 黑色偵探 / 懸疑推理題材",
    "- Bối cảnh trung tâm: Tháp Đồng Hồ Đêm Mưa & Thành phố Cảng Sương Mù.": "- 核心場景：雨夜鐘樓與迷霧港城。",
    "- Quy luật thời gian: Chuông đồng chỉ rung khi có sự cố chuyển giao ký ức hoặc mở khóa tầng áp mái.": "- 時間鐵律：唯有發生記憶同步異變或開啟閣樓密室時，青銅鐘才會鳴響。",
    "- Giọng văn chủ đạo: Noir tiết chế, giàu chi tiết giác quan (mưa, đồng thau, giấy da, ánh đèn bão).": "- 主導文風：克制冷峻的黑色推理風，富含感官細節（冷雨、黃銅、舊羊皮紙、風燈微光）。",
    "=== TỔNG HỢP STORY BIBLE CHÍNH THỨC (BẢN MẪU GUEST MODE) ===": "=== 官方設定集彙總（訪客模式範例工程） ===",
    "1. Bối cảnh & Luật ngầm:": "1. 背景設定與潛規則：",
    "- Vụ hỏa hoạn 20 năm trước thực chất là màn che đậy cho cuộc thử nghiệm lưu trữ ký ức của Giáo sư Hoàng tại Tháp Đồng Hồ.": "- 20 年前的大火實際上是為了掩蓋黃教授在鐘樓進行的記憶封存實驗。",
    "- Con số 13:00 trên mặt đồng hồ không chỉ thời gian mà là mã khóa cơ học nối lên gác chuông.": "- 鐘面上的 13:00 並非火災時間，而是通往頂層鐘樓的機械密碼。",
    "2. Tuyến nhân vật chính:": "2. 核心角色陣營：",
    "- Trần Minh Khôi (Chính): Thám tử lưu trữ, có vết sẹo cũ ở cổ tay trái, luôn giữ đồng hồ quả quýt vỡ kính.": "- 陳明魁（主角）：檔案調查員，左腕留有舊疤，隨身帶著表面碎裂的懷錶。",
    "- Lệ Băng (Đồng hành / Nghi phạm): Người giữ chùm chìa khóa đồng La Mã, nắm nửa sự thật về vụ hỏa hoạn.": "- 麗冰（搭檔 / 嫌疑人）：羅馬數字青銅鑰匙串的守門人，掌握著當年火災的一半真相。",
    "- Bé Miu (Nhân chứng bí ẩn): Xuất hiện trong hầm kín dù cửa khóa ngoài, cầm mảnh đồng khắc tên Giáo sư Hoàng.": "- 小喵（神秘目擊者）：在大門反鎖的地下室神秘現身，手中握有刻著黃教授名字的銅片。",
    "- Giáo sư Hoàng (Phản diện giấu mặt): Tác giả chuỗi sổ cái bìa đen và cỗ máy đồng bộ xung chuông.": "- 黃教授（幕後反派）：六本黑皮帳冊與鐘聲脈衝記憶同步裝置的締造者。",
    "3. Mạch phục bút đang chạy:": "3. 正在推進的伏筆脈絡：",
    "- Chìa khóa thứ tư hình bán nguyệt úp ngược -> Mở két sắt tầng áp mái.": "- 刻有倒置半月紋的第四把鑰匙 -> 開啟閣樓保險箱。",
    "- Vết thương cổ tay trái của Minh Khôi cộng hưởng với tần số chuông đồng.": "- 明魁左腕的舊傷與青銅大鐘的震動頻率產生共鳴。",
    "Nhân vật chính (Thám tử lưu trữ)": "主角（檔案調查偵探）",
    "Điềm tĩnh, quan sát tỉ mỉ chi tiết cơ học, ám ảnh công lý bị chôn vùi.": "沉著冷靜，細緻觀察機械構造細節，執著於追查被掩埋的正義。",
    "Ngắn gọn, sắc bén, dùng ngôi \"Tôi\" — gọi Lệ Băng bằng chức danh hoặc tên.": "簡短鋒利，自稱「我」——直呼麗冰其名或職務。",
    "Người giữ khóa Tháp Đồng Hồ": "鐘樓守鑰人",
    "Lạnh lùng bên ngoài nhưng cố bảo vệ bằng chứng gốc trước thế lực giấu mặt.": "外表冷漠，實則暗中守護原始證據以免落入幕後黑手。",
    "Mỉa mai nhẹ, hay đặt câu hỏi ngược để dò thái độ.": "略帶冷嘲，習慣用反問句試探對方立場。",
    "Nhân chứng bí ẩn": "神秘目擊者",
    "Nhạy bén với âm thanh bánh răng, xuất hiện tại những nơi tưởng chừng kín bưng.": "對齒輪聲極其敏銳，常在看似密閉的場所神秘現身。",
    "Ngây thơ nhưng câu nào cũng chứa ẩn ý cảnh báo.": "語氣天真無邪，但每句話都暗藏警示深意。",
    "Phản diện giấu mặt": "幕後隱藏反派",
    "Lập dị, tôn sùng việc \"khắc thời gian vào đồng thau\".": "性格怪癖，狂熱崇尚「將時間銘刻於黃銅之中」。",
    "Trang trọng, học thuật qua các trang sổ cái để lại.": "留存帳冊中的文風莊重嚴謹、充滿學術氣息。",
    "13:00 là mã khóa gác chuông chứ không phải giờ cháy": "13:00 是頂層鐘樓的機械密碼而非起火時間",
    "Lệ Băng, Giáo sư Hoàng (Minh Khôi chỉ mới suy ra ở Chương 3)": "麗冰、黃教授（明魁直到第 3 章才推理得出）",
    "Giới cảnh sát thành phố & nhân viên viện lưu trữ": "市政警方與檔案館工作人員",
    "Đường thông gió bí mật sau giá sách tầng hầm nối thẳng xuống bờ sông": "地下室書架後的秘密通風道直通河岸舊倉庫",
    "Trần Minh Khôi và Lệ Băng": "陳明魁與麗冰",
    "Vết sẹo cổ tay trái của Minh Khôi là dấu tích của chiếc vòng đồng thử nghiệm đầu tiên": "明魁左腕的舊疤是第一枚原型實驗銅環留下的烙印",
    "Giáo sư Hoàng, Lệ Băng": "黃教授、麗冰",
    "Trần Minh Khôi (cấm AI để lộ quá sớm trước Chương 5!)": "陳明魁（嚴禁 AI 在第 5 章前提前劇透！）",
    "Chìa khóa thứ tư khắc vệt bán nguyệt úp ngược": "刻有倒置半月紋的第四把鑰匙",
    "Trùng khớp mảnh giấy cháy dở tại viện lưu trữ, dùng mở két tầng áp mái.": "與檔案館拾獲的半焦殘紙完全吻合，用於開啟閣樓保險箱。",
    "Con búp bê thiếu một chiếc cúc mắt & mảnh đồng tên Giáo sư Hoàng": "缺了一顆鈕扣眼睛的布偶與刻有黃教授名字的銅片",
    "Cúc mắt bị rơi bên trong rãnh trượt cánh cửa thông gió bí mật.": "掉落的那顆鈕扣眼睛就卡在秘密通風門的滑軌槽內。",
    "Cổ tay trái của Minh Khôi nhói theo tần số chuông đồng": "明魁的左手腕隨青銅鐘聲頻率陣陣刺痛",
    "Chứng minh Minh Khôi từng trực tiếp có mặt trong phòng máy năm xưa.": "證明明魁當年曾親身處在鐘樓核心機房之中。",
