    "một luồng điện chạy dọc sống lưng, ánh mắt phức tạp, thở dài một tiếng, khẽ nhếch môi, không khỏi cảm thán": "一股電流順著脊背竄起, 眼神複雜, 輕嘆一口氣, 嘴角微微勾起, 不禁感嘆",
    "một luồng điện chạy dọc sống lưng, thở dài một tiếng, ánh mắt phức tạp, khẽ nhếch môi tạo thành một vòng cung, không khỏi cảm thán trong lòng, trong lòng dâng lên một cảm giác khó tả, bầu không khí bỗng trở nên tĩnh lặng đến đáng sợ, nụ cười nửa miệng đầy ẩn ý": "一股電流順著脊背竄起, 輕嘆一口氣, 眼神複雜, 嘴角勾起一抹弧度, 心中不禁感嘆, 心中湧起一股難以言喻的感覺, 氣氛突然安靜得可怕, 意味深長的半邊微笑",
