    "Tạo cảm giác điện ảnh ngay lập tức thay vì kể tính từ khô.": "即刻營造電影級畫面感，避免乾癟的形容詞堆砌。",
    "Căng thẳng / Che giấu bí mật": "緊張 / 隱瞞秘密",
    "↳ Chèn vào bản thảo": "↳ 插入稿件",
    "“Ánh đèn huỳnh quang nhấp nháy cắt ngang sống mũi hắn, hắt một vệt bóng xám dài xuống mặt bàn gỗ.”": "「閃爍的日光燈光線斜切過他的鼻樑，在木桌面上投下一道長長的灰影。」",
    "Hoảng hốt kìm nén": "強壓恐慌",
    "“Đầu ngón tay đang giữ quai tách khẽ khựng lại, làm gợn sóng nhỏ trong lòng chén trà sậm màu.”": "「握著茶杯柄的指尖微微一頓，在深色茶湯中盪起一圈細小的漣漪。」",
    "Cô độc / Lạnh lẽo đô thị": "孤獨 / 都市冷清",
    "“Ánh neon từ biển hiệu đối diện rỉ qua khe rèm chớp, nhuộm xanh bệ cửa sổ ẩm sương.”": "「對面招牌的霓虹燈透過百葉窗縫隙滲入，將沾滿潮氣的窗台染成一片幽藍。」",
    "Ngỡ ngàng sững sờ": "錯愕呆滯",
    "“Đồng tử mở to hơn bình thường một chút, phản chiếu nguyên vẹn ngọn lửa nhỏ đang rung trước gió.”": "「瞳孔比平常微微放大了一分，完整倒映出風中搖曳的微弱火苗。」",
    "Kiệt sức sau biến cố": "變故後的疲憊",
    "“Quầng thâm mờ dưới mi mắt khiến cái chớp mắt của cô chậm hơn bình thường nửa nhịp.”": "「眼瞼下淡淡的青黑，讓她每次眨眼都比平時慢了半拍。」",
    "Cảnh giác tột độ": "高度警覺",
    "“Ánh nhìn quét nhanh qua khe cửa khép hờ, dừng đúng hai giây ở vệt bùn mới in cạnh thảm chùi chân.”": "「視線迅速掃過虛掩的門縫，在門墊旁新印上的泥痕上恰恰停留了兩秒。」",
    "🌦️ Bối Cảnh Thời Tiết & Ánh Sáng Điện Ảnh (Chèn Nhanh Mở Cảnh)": "🌦️ 電影感天氣與光影背景（快速插入開場）",
    "🌧️ Mưa đêm & Đèn đường": "🌧️ 夜雨與路燈",
    "Chèn mở cảnh": "插入開場描寫",
    "Hạt mưa đập chéo vào mặt kính quán cà phê, kéo nhòe vệt đèn hậu đỏ rực bên kia đại lộ.": "雨點斜打在咖啡廳玻璃窗上，把大道對岸鮮紅的車尾燈拉成模糊的光痕。",
    "🌫️ Sương sớm vùng cao / Đà Lạt": "🌫️ 高原晨霧 / 大叻",
    "Lớp sương trắng bàng bạc vắt ngang hàng thông, thấm lạnh qua gấu áo len ngay khi cửa vừa hé.": "一層銀白色的晨霧橫亙在松林間，門剛推開一條縫，寒意便透過毛衣下擺滲了進來。",
    "☀️ Trưa nắng gắt ngột ngạt": "☀️ 悶熱毒辣的午後豔陽",
    "Mặt đường nhựa bốc hơi nóng hập hừ, ánh nắng chói chang khiến bóng đổ dưới chân co rút thành một chấm đen sắc lẹm.": "柏油路面蒸騰著灼人的熱浪，刺眼的烈日將腳下的影子縮成一團銳利的黑點。",
    "🌃 Đêm mất điện / Ánh nến": "🌃 停電之夜 / 燭光搖曳",
    "Bóng trần nhà rung rinh theo ngọn bấc đèn cầy mỗi lần có luồng gió lùa qua khe cửa gỗ mục.": "每當穿堂風從腐朽木門的縫隙鑽入，天花板上的影子便隨著燭芯一同晃動。",
    "🍂 Gió thu cuối chiều": "🍂 傍晚微涼的秋風",
