    "Mưa đêm vẫn rơi đều trên mái hiên cổ kính, phản chiếu ánh đèn vàng ấm áp xuống mặt đường lát đá ướt đẫm.": "夜雨依舊均勻地落在古舊的屋簷上，將溫暖的黃燈光影映照在濕漉漉的石板路上。",
