    "🇻🇳 Chào mừng bạn tới Bi's Novel Writing Studio với bộ biểu tượng chân dung mới! Ngay đầu cổng là nút Mai Hải Đăng (Bi), nút to Ủng hộ Đăng và nút Tải App về thiết bị ngay.": "🇻🇳 歡迎來到全新頭像圖示版 Bi 輕小說創作工坊！入口最上方設有 Mai Hải Đăng (Bi) 按鈕、醒目的支持 Đăng 按鈕以及立即下載應用程式到裝置的按鈕。",
