    "Ngay phía trên Cổng Kết Nối An Toàn là cụm nút tác giả Mai Hải Đăng (Bi), nút \"☕ Ủng hộ Đăng để Đăng có động lực phát triển web :D\" nổi bật và nút \"📲 Tải App về thiết bị ngay\".": "安全連線入口上方即為作者 Mai Hải Đăng (Bi) 按鈕組、醒目的「☕ 支持 Đăng，給 Đăng 繼續開發網頁的動力 :D」按鈕，以及「📲 立即下載應用程式到裝置」按鈕。",
    "Dán Gemini API Key (bấm Xác thực Flash-Lite) & Chọn thư mục ổ cứng thật (Mod 04-05) hoặc dùng trên Mobile PWA để bật sao lưu 3 tầng.": "貼上 Gemini API Key（點擊驗證 Flash-Lite）並選擇真實硬碟資料夾（Mod 04-05），或在手機 PWA 上使用以開啟 3 層備份。",
