    "📑 20 Mốc Chức Năng Chi Tiết (~10 Phút) · Đủ 44 Module (Chạm Để Tua Tới)": "📑 20 個詳細功能節點（約 10 分鐘）· 涵蓋全部 44 個模組（點擊跳轉）",
    "1. Cổng Kết Nối Đầu Vào, Ủng Hộ Đăng, Tải App PWA & 6 Màn Hình (Mod 01-05, 29, 30, 35)": "1. 入口連線閘道、支持 Đăng、下載 PWA 應用程式與 6 大畫面（Mod 01-05, 29, 30, 35）",
    "Giới thiệu cụm nút đầu cổng (\"Web do Mai Hải Đăng (Bi) phát triển\", nút to nổi bật \"Ủng hộ Đăng để Đăng có động lực phát triển web :D\", nút \"Tải App về thiết bị ngay\"), xác thực API Key 3 tầng & 6 Tab": "介紹入口頂部按鈕組（「由 Mai Hải Đăng (Bi) 開發的網頁」、醒目的「支持 Đăng，給 Đăng 繼續開發網頁的動力 :D」按鈕、「立即下載應用程式到裝置」按鈕）、3 層 API Key 驗證及 6 個分頁",
