    "Bàn viết chuẩn trang sách, tạo chương 1 chạm, chuẩn hóa ngoặc thoại Việt (Mod 23), duyệt chữ AI theo từng cụm màu kiểu Google Docs (Mod 11), Ngũ quan, Anti-Cliché & Lore Whisper (Mod 24-25).": "類書頁排版寫作台、一鍵新增章節、規範化越南語對話引號（Mod 23）、Google Docs 風格分色區塊 AI 審閱（Mod 11）、五感描寫、Anti-Cliché 去套路與 Lore Whisper 設定低語（Mod 24-25）。",
