    "Đang gõ văn bản hoặc nhấn Backspace thì trang bị tải lại": "正在輸入文字或按 Backspace 鍵時頁面突然重新載入",
    "Luôn lưu thư mục truyện tách riêng khỏi thư mục mã nguồn HTML.": "請始終將小說資料夾與 HTML 原始碼資料夾分開存放。",
    "Module 36 (Zero-Reload Save Shield) đang tự động chặn tín hiệu reload từ WebSocket và sự kiện form/navigation.": "Module 36 (Zero-Reload Save Shield) 正在自動攔截來自 WebSocket 以及表單/導覽事件的重新載入訊號。",
