    "Ví dụ: Chữ vàng trên nền xám khó đọc, hai nút đè viền lên nhau, trang tự load lại về cổng kết nối...": "例如：灰底黃字難以看清、兩個按鈕邊框重疊、頁面自動重新載入退回連線入口……",
