    "WEB VIẾT TIỂU THUYẾT CỦA BI — GHI CÔNG TÁC GIẢ": "Bi 輕小說創作工坊 — 作者致謝名單",
    "Được hoàn thiện bởi tác giả Mai Hải Đăng (nickname: Bi) trong 3 ngày đồng hành cùng AI": "由作者 Mai Hải Đăng（綽號：Bi）與 AI 攜手歷時 3 天打造完成",
    "\"Mình lấy cảm hứng từ nỗi đau không có web riêng, mình thì không biết lập trình nên là mình làm hơi lâu, cụ thể là 3 ngày với AI, mong mọi người thông cảm nếu có sai sót nha, có gì cứ report bug cho m": "「我的靈感源於沒有專屬寫作網頁的痛點。因為不懂程式設計，做起來稍微久了一點，具體來說是和 AI 一起花了 3 天時間。若有疏漏之處還請大家多多包涵，有任何問題歡迎隨時向我回報 Bug！」",
    "Giải nghĩa nhỏ:": "小說明：",
    "Góc nhỏ giải nghĩa tên gọi: \"Bi\" chính là nickname ở nhà thân mật của tác giả Mai Hải Đăng, vì vậy đứa con tinh thần này mới mang cái tên gần gũi là \"Bi's Novel Writing Studio\".": "名稱由來小說明：「Bi」正是作者 Mai Hải Đăng 在家裡的親切綽號，因此這份心血之作才取名為「Bi 輕小說創作工坊」。",
    "★ BẢNG PHÂN VAI & THỰC HIỆN ĐỘC LẬP ★": "★ 角色分工與獨立製作名單 ★",
    "✦ KHỞI XƯỚNG & TẦM NHÌN ✦": "✦ 發起人與願景 ✦",
    "Author sản phẩm & Người khởi xướng dự án": "產品作者與專案發起人",
    "Từ nhu cầu có một bàn viết chuyên sâu dành riêng cho người sáng tác Light Novel dài hơi.": "源於為長篇輕小說創作者打造專屬深度寫作台的初衷。",
    "✦ TRẢI NGHIỆM SÁNG TÁC ✦": "✦ 創作體驗 ✦",
    "Thiết kế luồng 6 Màn Hình Studio & Bàn viết tập trung": "設計 6 大畫面工坊流程與專注寫作台",
    "Tách bạch viết thảo, quản lý chương, AI 5 chế độ, Story Bible, không gian âm nhạc và xuất bản.": "清晰分離正文撰寫、章節管理、5 模式 AI、故事聖經、音樂氛圍空間與出版匯出。",
    "✦ CHỈ HUY HỆ THỐNG AI ✦": "✦ AI 系統指揮 ✦",
    "Kiến tạo quy trình 5 Chế độ AI, Ma trận Ai Biết Gì & Prompt Tổng": "建構 5 大 AI 模式流程、資訊差矩陣與總指令架構",
    "Kết nối Mode 2 lập dàn ý sang Mode 1 viết sâu, chặn sáo ngữ AI và ký hiệu rối mắt.": "打通 Mode 2 列大綱與 Mode 1 深度寫作的銜接，封鎖 AI 套話與雜亂符號。",
    "✦ AN TOÀN DỮ LIỆU ✦": "✦ 資料安全 ✦",
    "Định hình Tự Lưu 3 Tầng, Ghi nhớ Thư mục Ổ cứng & Khiên Chống Reload": "確立 3 層自動儲存、本機硬碟目錄記憶與防重新載入護盾",
    "Đặt ưu tiên số 1 là bảo vệ từng con chữ tác giả gõ ra không bao giờ bị bay mất.": "將保護作者敲下的每一個字永不遺失置於第一優先級。",
    "✦ KIỂM THỬ THỰC CHIẾN ✦": "✦ 實戰測試 ✦",
    "Thử nghiệm từng tính năng, soi từng điểm cấn và sửa lỗi liên tục": "逐項實測每個功能，檢視每一處不順手之處並持續修復問題",
    "Kiên nhẫn kiểm tra trên từng tab, ghi nhận từng chi tiết hiển thị để mài giũa hoàn thiện.": "耐心排查每個分頁與每處顯示細節，打磨至臻完善。",
    "✦ ĐÓNG GÓI CÙNG AI ✦": "✦ 與 AI 協同建構 ✦",
    "Điều phối xây dựng toàn bộ ứng dụng web trong 3 ngày cùng AI": "在 3 天內與 AI 協同調度完成整套網頁應用程式的建構",
    "Chứng minh rằng niềm đam mê kể chuyện vẫn có thể tạo ra công cụ riêng dù xuất phát điểm không phải lập trình viên.": "證明只要懷抱說故事的熱愛，即便不是程式設計師出身，也能親手打造屬於自己的創作工具。",
    "⏳ HÀNH TRÌNH 3 NGÀY ĐỒNG HÀNH CÙNG AI": "⏳ 與 AI 同行的 3 天歷程",
    "NGÀY 1": "第 1 天",
    "Ngày 1 — Nỗi Đau Không Có Web Riêng & Viên Gạch Đầu Tiên": "第 1 天 — 沒有專屬網頁的痛點與第一塊基石",
    "Bắt đầu từ cảm giác khó chịu khi viết tiểu thuyết dài tập trên các trình soạn thảo rời rạc: hay quên chi tiết nhân vật cũ, file Word nặng nề, và AI viết rời rạc không nhớ bối cảnh.": "源於在零散編輯器中創作長篇小說的種種困擾：容易遺忘舊角色細節、Word 檔案臃腫沉重，以及 AI 寫作斷層、記不住上下文背景。",
    "Hình thành ý tưởng Studio 6 màn hình tách biệt hoàn toàn không gian viết và công cụ phụ.": "構思出將寫作空間與輔助工具完全分離的 6 畫面工坊理念。",
    "Đặt nền móng lưu trữ trực tiếp xuống thư mục ổ cứng người dùng + tự lưu dự phòng.": "奠定直接儲存至使用者本機硬碟資料夾 + 自動備份的基礎架構。",
    "Khởi tạo linh vật Trợ Lý Viên Bi Số 8 làm bạn đồng hành khi bí ý.": "打造 8 號球助手吉祥物，作為卡文時的創作夥伴。",
    "NGÀY 2": "第 2 天",
    "Ngày 2 — Story Bible Chống Quên, 5 Chế Độ AI & Không Gian Cảm Hứng": "第 2 天 — 防遺忘故事聖經、5 大 AI 模式與靈感氛圍空間",
    "Nhận ra viết hàng trăm chương sẽ làm AI thông thường quên cốt truyện nên tích hợp cầu nối NotebookLM, ma trận Ai Biết Gì, bảng phục bút cùng trình phát nhạc MP3 và hiệu ứng nền 60FPS.": "意識到動輒上百章會讓普通 AI 遺忘劇情，於是整合了 NotebookLM 橋樑、資訊差矩陣、伏筆表，以及 MP3 播放器與 60FPS 動態背景。",
    "Tách 5 Chế độ AI chuyên sâu từ lập dàn ý đến thanh tra logic và vẽ biểu đồ SVG.": "拆分 5 大專業 AI 模式，涵蓋大綱規劃、邏輯審查與 SVG 圖表繪製。",
    "Bổ sung trình đọc giọng tự nhiên Neural, đồng hồ Pomodoro đồng bộ và xuất sách PDF/DOCX/EPUB.": "新增自然 Neural 語音朗讀器、同步 Pomodoro 番茄鐘以及 PDF/DOCX/EPUB 電子書匯出。",
    "Xây dựng Cổng Kết Nối API Key + Thư mục an toàn trước khi vào bàn viết.": "在進入寫作台前搭建起安全的 API Key + 資料夾連線入口。",
    "NGÀY 3": "第 3 天",
    "Ngày 3 — Lắng Nghe Từng Lỗi Nhỏ, Tối Ưu Giao Diện & Mở Kênh Report Bug": "第 3 天 — 打磨每處小細節、最佳化介面與開啟 Bug 回報管道",
    "Dành trọn ngày thứ 3 kiểm thử khắt khe từng lỗi thực tế: sửa thanh công cụ Tab 2, nối mạch Mode 2 sang Mode 1, gọt bỏ ký hiệu AI thừa, làm tối rõ các menu chọn và lắp đặt Khiên chống tải lại trang.": "第 3 天全天嚴苛實測真實問題：修復 Tab 2 工具列、打通 Mode 2 至 Mode 1 的脈絡、剔除多餘 AI 符號、最佳化下拉式選單暗色對比度，並加裝防重新載入護盾。",
    "Khắc phục lỗi lọc chương Nháp / Đã duyệt và chống đè chữ ở thanh tiêu đề Tab 1-2.": "修復草稿 / 已核准章節篩選異常，並徹底解決 Tab 1-2 標題列文字重疊問題。",
    "Hoàn thiện hộp thoại Báo Lỗi (Report Bug) và màn Ghi công Author gửi lời tri ân tới người dùng.": "完善錯誤回報（Report Bug）視窗與作者致謝頁面，向各位使用者表達感謝。",
    "Mở kênh kết nối trực tiếp qua Gmail và Facebook để tiếp tục hoàn thiện mỗi ngày.": "開通 Gmail 與 Facebook 直連管道，以便每日持續傾聽與完善。",
