    "💡 Vì sao là \"Web Viết Tiểu Thuyết Của Bi\"? Tên gọi \"Bi\" chính là nickname ở nhà thân mật của tác giả Mai Hải Đăng — đặt tên như vậy để góc sáng tác luôn giữ cảm giác gần gũi như ở nhà mình vậy.": "💡 為什麼叫「Bi 輕小說創作工坊」？「Bi」正是作者 Mai Hải Đăng 在家裡的親切暱稱 —— 這樣命名，是希望這個創作角落永遠保有像家一樣親切溫暖的歸屬感。",
