    "▾ Cổng Xác Thực Gemini API Key Qua Flash-Lite & Link AI Studio 1-Click": "▾ 透過 Flash-Lite 驗證 Gemini API Key 及一鍵跳轉 AI Studio 入口",
    "Mở Cổng / Kiểm Tra Key & Thư Mục": "開啟入口 / 檢查 Key 與資料夾",
    "🕒 Dùng khi nào:": "🕒 適用時機：",
    "Mỗi lần mở web lần đầu tiên, khi đổi tài khoản Google AI Studio mới hoặc khi vừa quay lại trình duyệt để rà soát nhanh trạng thái Key trước lúc sáng tác.": "每次首次開啟網頁、更換新的 Google AI Studio 帳號，或回到瀏覽器準備寫作前快速核對 Key 狀態時。",
    "📋 Các bước thực hiện chuẩn:": "📋 標準操作步驟：",
    "Bấm nút \"Mở Google AI Studio Để Copy API Key Ngay\" để lấy khóa AIza... hoặc AQ... từ tài khoản Google của bạn.": "點擊「立即開啟 Google AI Studio 複製 API Key」按鈕，從您的 Google 帳號取得 AIza... 或 AQ... 金鑰。",
    "Dán khóa vào ô nhập liệu; hệ thống tự động gọi mô hình Flash-Lite nhẹ nhất để kiểm tra sống-chết mà không tốn đáng kể hạn mức.": "將金鑰貼上到輸入框；系統將自動呼叫最輕量的 Flash-Lite 模型進行連通性檢測，幾乎不消耗額度。",
    "Nếu trước đó bạn đã lưu Key và Thư mục, Cổng kết nối vẫn hiện lại ngắn gọn để bạn rà soát và bấm nút xanh lá vào Studio.": "如果您之前已儲存 Key 和資料夾，連線入口仍會簡潔顯示以便您核對，點擊綠色按鈕即可進入 Studio。",
    "💡 Mẹo tác giả:": "💡 作者小撇步：",
    "Bạn có thể mở lại Cổng kết nối bất kỳ lúc nào ngay trong Tab 6 bằng nút \"Kiểm Tra / Đổi Key & Thư Mục Kết Nối\" để thay Key mới mà không cần tải lại trang.": "您可以隨時在 Tab 6 點擊「檢查 / 更換 Key 與關聯資料夾」重新開啟連線入口，無需重新整理頁面即可更換新 Key。",
