    "Mở Tra Cứu BM25 tại Tab 2": "在 Tab 2 開啟 BM25 檢索",
    "▸ Chuẩn Hóa Câu Thoại Nhanh & Công Cụ Biên Tập Trong Khay Thu Gọn Tab 2": "▸ Tab 2 收合列中的快速對話規範與編輯工具",
    "Đi tới nút Chuẩn Hóa Thoại Tab 2": "前往 Tab 2 規範對話按鈕",
    "▸ 5 Chế Độ Viết Tiểu Thuyết Chuyên Biệt (Từ Viết Nháp, Tham Mưu Đến Vẽ Sơ Đồ)": "▸ 5 種專業小說創作模式（涵蓋正文起草、劇情參謀到圖表繪製）",
    "Mở Trung Tâm AI 5 Chế Độ Tab 3": "開啟 Tab 3 五模式 AI 中心",
    "▾ Đủ Hệ Gemini 4 (Hydrogen / Argon / Carbon) + Pro / Flash & Tư Duy Thấp / TB / Cao / XHIGH": "▾ 完整 Gemini 4 系列 (Hydrogen / Argon / Carbon) + Pro / Flash 與 低/中/高/XHIGH 思考深度",
    "Mở Chọn Mô Hình & Tư Duy Tab 3": "開啟 Tab 3 模型與思考深度選擇",
    "Khi cần viết chương sâu sắc hoặc kiểm toán logic nhiều tầng (chọn Gemini 4 Hydrogen + Tư duy Cao/XHIGH), viết đại tự sự (Argon 4), hoặc nháp nhanh tiết kiệm quota (Flash / Flash-Lite).": "當需要撰寫深度章節或進行多層邏輯稽核時（選 Gemini 4 Hydrogen + 高/XHIGH 思考）、撰寫宏大敘事時（Argon 4），或節省額度快速起草時（Flash / Flash-Lite）。",
    "Trong Trung tâm điều khiển AI Tab 3, Cổng Bước 2, Chế độ 5, Tab 4 Bible hoặc Trợ lý Viên Bi Số 8, chọn mô hình mong muốn ở danh sách \"Mô hình Gemini\".": "在 Tab 3 AI 控制中心、第 2 步入口、模式 5、Tab 4 故事聖經或 8 號球助手中，於「Gemini 模型」清單中選擇目標模型。",
    "Chọn tiếp mức \"Tư duy: Thấp / Trung bình / Cao / XHIGH\" để điều chỉnh chiều sâu suy luận của AI đồng bộ tới API Key.": "接著選擇「思考深度：低 / 中 / 高 / XHIGH」，將 AI 推理深度同步套用到您的 API Key。",
    "Nếu mô hình Pro hoặc Argon-4 bị giới hạn endpoint trên Key miễn phí, hộp thoại dự phòng hiện sẵn link copy câu lệnh & link mở thẳng \"Gemini của bạn\".": "如果 Pro 或 Argon-4 在免費 Key 上受限於端點，備用視窗會直接提供複製指令連結與一鍵開啟「您的 Gemini」的連結。",
    "Khi mở hộp thoại dự phòng Pro/Argon-4, chỉ cần bấm chữ \"câu lệnh dưới đây\" là toàn văn Prompt Tổng Hợp tự động chép gọn vào clipboard cho bạn dán sang Gemini Web.": "當開啟 Pro/Argon-4 備用視窗時，只需點擊「下方指令」文字，完整綜合提示詞就會自動複製到剪貼簿供您貼到 Gemini 網頁版。",
    "▸ Đồng Hồ Hạn Mức Ngắn Hạn (5 Giờ) & Dài Hạn (Tuần) Kèm Link Gemini Account Live": "▸ 短期（5 小時）與長期（每週）額度儀表板及即時 Gemini 帳號連結",
    "Xem Hạn Mức 5h & Tuần Ở Tab 3": "在 Tab 3 查看 5h 與每週額度",
