    "▾ Cẩm Nang Chống Quên Cho Truyện Dài Hàng Trăm Chương Cùng Google NotebookLM": "▾ 搭配 Google NotebookLM 的百章長篇防遺忘指南",
    "Đi tới Cẩm Nang NotebookLM Tab 4": "前往 Tab 4 NotebookLM 指南",
    "Khi tác phẩm của bạn đã vượt 15-30 chương trở lên hoặc khi bạn muốn tái tổng hợp một bộ Story Bible siêu chi tiết không sót bất kỳ manh mối nào từ đầu truyện.": "當您的作品已超過 15–30 章，或希望重新梳理一份不遺漏開篇任何線索的超詳盡故事聖經時。",
    "Vào Tab 4, nhìn thẻ nổi bật \"Mẹo Giữ Ký Ức Cho Truyện Dài Hàng Trăm Chương Với NotebookLM\".": "進入 Tab 4，找到醒目卡片「百章長篇使用 NotebookLM 保持記憶的技巧」。",
    "Bấm nút \"1. Tải PDF Gộp Toàn Bộ Chương\" để đóng gói tất cả từ Chương 1 -> Chương cuối thành 1 bản PDF.": "點擊「1. 下載全部章節合併 PDF」按鈕，將第 1 章 -> 最後一章打包為 1 份 PDF。",
    "Bấm \"2. Mở Ngay Sổ Tay NotebookLM ↗\", tải PDF vừa xuất vào đó, rồi bấm \"3. Sao Chép Prompt Tổng Hợp Story Bible Chi Tiết\" dán vào NotebookLM — nhận lại toàn văn Story Bible chuẩn mực và dán ngược vào khung Tab 4.": "點擊「2. 立即開啟 NotebookLM 筆記本 ↗」，上傳剛剛匯出的 PDF，再點擊「3. 複製詳盡故事聖經彙整提示詞」並貼到 NotebookLM — 取得標準故事聖經全文後再貼回 Tab 4 輸入框。",
    "NotebookLM đọc cực khỏe hàng triệu chữ nguồn cùng lúc mà không bị trôi trí nhớ, cực kỳ phù hợp làm bộ nhớ dài hạn song song cùng Studio!": "NotebookLM 可同時穩定讀取數百萬字源文本而不遺忘，非常適合作為 Studio 的平行長期記憶庫！",
