    "Chỉ đạo AI: Sử dụng kỹ thuật Match Cut điện ảnh: Kết thúc cảnh trước bằng hình ảnh một vật thể (ví dụ: tàn thuốc đỏ rực, giọt nước mưa, vòng xoáy tách cà phê) và mở đầu cảnh này bằng một hình ảnh có hình dáng/chuyển động tương tự ở không gian mới. Ví dụ văn phong: * * * Vệt khói trắng mảnh mai từ đầu điếu thuốc vừa tắt ngấm trong căn phòng thẩm vấn dường như nối dài ra, hòa vào màn sương mù dày đặc đang bao phủ lấy bến cảng phía Đông lúc hai giờ sáng.": "AI 指導：運用電影級 Match Cut（匹配剪輯）技巧：以上一場景中的某個物體畫面收尾（如暗紅煙灰、雨滴、咖啡杯漩渦），並在新場景開頭以形態或動態相似的畫面承接。文風範例：* * * 審訊室裡剛剛掐滅的菸頭升起一縷纖細白煙，彷彿無限延伸出去，融入凌晨兩點籠罩東碼頭的濃霧之中。",
    "e.g., Rooftop café": "例：頂樓咖啡館",
