    "Viết tiếp ngay sau tiếng chuông ở cuối Chương 3: Trần Minh Khôi và Lệ Băng bước lên sàn gỗ gác chuông tối đen, phát hiện cuộn băng ghi âm nằm sau quả lắc đồng. Giữ đúng xưng hô Tôi/Anh - Cô, tuyệt đối không dùng các cụm sáo ngữ bị cấm và không để lộ bí mật vết sẹo cổ tay quá sớm.": "緊接第 3 章末尾的鐘聲續寫：Trần Minh Khôi 與 Lệ Băng 踏上漆黑的鐘樓木地板，在銅鐘擺後方發現一捲錄音帶。保持「我/他 - 她」稱謂一致，嚴禁使用任何違禁陳腔濫調，切勿過早洩漏手腕傷疤的秘密。",
    "Viết một phân đoạn hồi tưởng ngắn (khoảng 300 từ) xen góc nhìn POV ngôi thứ ba theo Trần Minh Khôi khi nhớ về ánh lửa hắt lên mặt kính đồng hồ quả quýt bị vỡ, giữ nguyên bí mật về Giáo sư Hoàng cho chương sau.": "撰寫一段簡短回憶片段（約 300 字），以 Trần Minh Khôi 的第三人稱 POV 視角切入，追憶火光映在碎裂懷錶玻璃上的情景，並將關於 Giáo sư Hoàng 的秘密保留至下一章。",
    "✍️ [CHẾ ĐỘ 1 — VIẾT BẢN THẢO CHÍNH THỨC] Nhập diễn biến chương truyện, tâm lý nhân vật, bối cảnh không gian hoặc phân cảnh bạn muốn AI triển khai chi tiết (3.000 - 4.000+ từ) tại đây... Ví dụ gợi ý để viết sâu sắc, không tua nhanh: - Cảnh 1 (Mưa khuya ở sảnh ga): Nhân vật A giữ im lặng khi nhận phong thư nặc danh, miêu tả chậm cảm giác lạnh gáy, mùi nước mưa và ánh đèn vàng hắt lên ngón tay run. - Cảnh 2 (Đối thoại căng thẳng): Cuộc chạm trán với Nhân vật B, dùng lời nói ẩn ý chứ chưa vội lật bài ngửa ngay. - Lưu ý: Hệ thống tự động lồng ghép dàn ý đã phát triển ở Chế độ 2 (nếu có) + Story Bible + Mốc chuyển phân cảnh + Ma trận Ai Biết Gì.": "✍️ [模式 1 — 正式正文起草] 在此輸入您希望 AI 深入展開的章節劇情、角色心理、空間氛圍或具體橋段（3,000 - 4,000+ 字）... 深度慢寫範例建議：- 場景 1（車站大廳深夜雨）：角色 A 收到匿名信件時保持沉默，慢節奏刻劃後頸寒意、雨水氣息與照在顫抖指尖的暖黃燈光。- 場景 2（緊張對話）：與角色 B 正面交鋒，運用含蓄試探而非急於攤牌。- 提示：系統會自動整合模式 2 生成的大綱（如有）+ 故事聖經 + 轉場標記 + 知情矩陣。",
    "✅ Duyệt & Chốt Bản Thảo — Tự Động Cập Nhật Story Bible": "✅ 核准並鎖定草稿 — 自動更新故事聖經",
