    "Đồng hồ trên tháp chuông vừa điểm mười hai tiếng, và đúng lúc ấy toàn bộ đèn hành lang đồng loạt tắt phụt.": "鐘樓上的大鐘剛剛敲響十二下，就在那一刻，整條走廊的燈光齊刷刷地熄滅了。",
