    "API Key liên kết đồng bộ thời gian thực tại cả Trung tâm AI, Chat Bi Số 8, Mode 5 và tự động phát hiện 0 điểm cuối live trên tài khoản của bạn.": "連結的 API Key 在 AI 中心、Bi 8號球聊天與 Mode 5 之間即時同步，並自動在您的帳號上偵測到 0 個線上端點。",
