    "Read sample drafts, Word Stats, AI Cliché Scanner, Five-Senses Dictionary, Dialogue Formatter, SVG Relationship Graph & trial Diff Review in RAM": "閱讀範例草稿、字詞統計、AI 老套詞掃描、五感詞典、對話規範化、SVG 關係圖與 RAM 試用 Diff 審閱",
    "Chạy 10 Prompt Mẫu & Kết Quả Mô Phỏng Cho Đủ 5 Chế Độ (Chế độ 1 → 5) + Hỏi Mẫu Bi Số 8": "執行涵蓋全部 5 種模式（模式 1 → 5）的 10 個範例提示詞與模擬結果 + Bi 8號球範例提問",
    "Duyệt & Chốt Bản Thảo Thông Minh (tự động bóc tách AI vào Story Bible + ghi file đã duyệt lên ổ cứng)": "智慧核准並鎖定草稿（AI 自動擷取至故事聖經 + 將已核准檔案寫入硬碟）",
    "🔐📁 CẦN GEMINI API KEY & THƯ MỤC LÀM VIỆC": "🔐📁 需要 GEMINI API KEY 與工作資料夾",
    "Duyệt & Chốt Bản Thảo Thông Minh": "智慧核准並鎖定草稿",
    "Tính năng này yêu cầu cả Gemini API Key lẫn Thư mục làm việc. Bạn đang ở chế độ dùng thử (Guest Mode). Để sử dụng trọn vẹn tính năng này và bảo vệ bản thảo an toàn, bạn cần liên kết ở màn hình chính (Reload lại web để liên kết) bằng việc sao chép và dán Key API của Gemini ở Bước 1 cũng như chọn Thư mục làm việc ở Bước 2 — tất cả thao tác chỉ tốn chưa đầy 2 phút!": "此功能同時需要 Gemini API Key 與工作資料夾。您目前正處於試用模式（Guest Mode）。若要完整使用此功能並安全保護書稿，請返回主畫面（重新載入網頁即可連線），在第 1 步複製貼上您的 Gemini API Key，並在第 2 步選擇工作資料夾——全部操作只需不到 2 分鐘！",
