    "Bạn nên làm rõ bạn muốn AI viết mấy phân cảnh (Càng chia nhỏ càng tốt), mạch truyện nhanh hay chậm, mỗi phân cảnh bao nhiêu từ... Cơ bản như vậy cộng với cái story bible và cái cốt truyện có AI tư vấn bên cạnh nữa là mình thấy oke rồi đó bạn, mình cũng hay viết tới đó thôi hẹ hẹ": "建議先說明希望 AI 寫幾個分場（拆得越細越好）、劇情節奏快慢、每個分場大約多少字……基本寫清楚這些，再搭配旁邊的 Story Bible 設定集與 AI 參謀劇情，效果就已經很穩了，我平常也差不多寫到這一步而已哈哈。",
