    "Đề xuất các phương án phát triển tình tiết đột phá, nút thắt bất ngờ (plot twist), cách gỡ bí kịch bản và phương án thu hồi phục bút.": "提供突破性的劇情發展方案、意外反轉節點、卡文破解思路以及伏筆回收方案。",
    "🔍 Chế độ 3: Thanh Tra Logic, Mâu Thuẫn Thời Gian & Ma Trận Ai Biết Gì (Continuity Audit)": "🔍 模式 3：邏輯漏洞、時間軸衝突與資訊差審查",
    "Rà soát nghiêm ngặt toàn bộ lỗ hổng logic, sai lệch dòng thời gian, nhân vật biết trước thông tin chưa được tiết lộ (OOC / Epistemic Leak) và phục bút bị bỏ quên.": "嚴格排查所有邏輯漏洞、時間軸錯位、角色提前知曉未公開機密（OOC / 資訊越界洩漏）以及遺忘的伏筆。",
    "✨ Chế độ 4: Biên Tập Chuyên Sâu, Gọt Văn Chống Sáo Rỗng & Chuẩn Hóa Thoại (Literary Polish)": "✨ 模式 4：深度文學潤飾、去套話打磨與對白規範化",
    "Nâng cấp chất lượng văn chương của bản thảo, loại bỏ 100% từ ngữ sáo rỗng (Anti-Cliché), chuẩn hóa định dạng hội thoại và làm giàu nhạc tính tiếng Việt.": "全面提升文稿文學質感，100% 剔除 AI 套話與陳腔濫調，統一對話格式並增強行文韻律感。",
