    "Trích xuất cấu trúc sự kiện, mạng lưới quan hệ nhân vật và dòng thời gian thành sơ đồ trực quan kèm báo cáo đối chiếu xuyên chương.": "將事件結構、角色關係網與時間軸提取為視覺化圖譜，並附帶跨章節矛盾核查報告。",
    "🧪 KHUYÊN DÙNG #1 · SIÊU SUY LUẬN XHIGH — CÂN BẰNG TOÀN DIỆN GEMINI 4": "🧪 首選推薦 #1 · XHIGH 超強推理 — Gemini 4 全能均衡版",
