    "Sao chép toàn bộ Prompt Tổng Hợp và mở ngay Gemini Web trong tab mới": "複製完整綜合提示詞並立即在新分頁開啟 Gemini 網頁版",
    "Mở thẳng Gemini Web của bạn trong tab mới": "在新分頁直接開啟您的 Gemini 網頁版",
