    "21. Luồng Phát Trực Tiếp / PiP, Đồng Bộ Nền YouTube, Cỡ Chữ Toàn Web & Mục #5 Linh Tinh (v46)": "21. 流暢播控 / PiP 子母畫面、YouTube 背景影片同步、全域字號與第 5 雜項趣味欄 (v46)",
    "NATIVE PIP · BG VIDEO SYNC · SYSTEM FONT SCALE · CHỨC NĂNG LINH TINH": "原生子母畫面 · 背景影片同步 · 全域字體縮放 · 趣味雜項功能",
    "Nâng cấp phát YouTube mượt mà trên cả Mobile & Desktop (Repeat/A-B không đen màn hình, đồng bộ phát/dừng/tua sang Background, System PiP), Cỡ Chữ Hệ Thống 4 mức & Mục #5 Chức Năng Linh Tinh + Chuỗi điểm danh!": "全面升級行動端與桌面端 YouTube 播放（單曲循環/A-B 循環不黑畫面、播放/暫停/進度拖曳即時同步至全站背景、系統子母畫面 PiP）、四檔全域字體大小及分頁 6 第 5 趣味欄與連續簽到勳章！",
    "Khi bấm Lặp video (Repeat) hoặc Lặp đoạn A–B trên YouTube, trình phát giữ nguyên luồng đang chạy không bị đen hay gián đoạn; Video Background tự động khớp Tạm dừng / Phát tiếp / Tua theo khung chính.": "點擊 YouTube 重複播放或 A–B 區間循環時，播放器保持目前串流不黑畫面不中斷；網頁動態背景影片自動即時跟隨主畫面暫停、繼續與進度拖曳。",
    "Đổi Cỡ Chữ Toàn Web (Nhỏ · Bình thường · To · Rất to) trực tiếp trên Thanh Header hoặc Tab 5/Tab 6; giữ chuỗi Điểm danh 7/21/90/365 ngày nhận huy hiệu Tiểu thuyết gia.": "直接在頂部列或分頁 5/6 切換全站字號（小 · 標準 · 大 · 特大）；保持 7 / 21 / 90 / 365 天連續簽到即可解鎖各階小說家勳章。",
    "Khám phá Ô #5 \"Chức năng linh tinh\" ở Tab 6 (giữa Ô 4 và Tải App) với SaLưới mini game, kỷ niệm đời đầu & chế độ đa ngôn ngữ đầy đủ kể cả khung Prompt và định dạng ngày giờ bản địa!": "探索分頁 6 中第 4 欄與下載應用之間的第 5 欄「雜項趣味功能」，內含 SaLưới 小遊戲、早期粉絲致謝牆，並完善涵蓋主提示詞框架與各國原生日期格式的 6 語在地化！",
    "Repeat / A–B Loop Mượt Mà & Đồng Bộ Nền YouTube (Mod 39/40)": "流暢循環 / A–B 片段重複與 YouTube 背景同步 (Mod 39/40)",
    "Bấm Lặp video hoặc Lặp đoạn A–B nay giữ nguyên khung phát không đen màn hình, đồng thời Video Background luôn Dừng/Chạy/Tua đồng bộ tức thì theo trình phát chính.": "現在點擊整片循環或 A–B 片段循環可保持畫面不黑畫面，同時全站背景影片會即時跟隨主播放器暫停、播放或拖曳進度。",
    "Cỡ Chữ Toàn Web (4 Mức) & Chuỗi Điểm Danh Huy Hiệu": "4 檔全站字號縮放與連續簽到勳章",
    "Tùy chỉnh Cỡ chữ hệ thống (Nhỏ / Bình thường / To / Rất to) đồng bộ Header, Tab 5 & Tab 6; điểm danh giữ chuỗi 7, 21, 90 và 365 ngày để mở khóa các huy hiệu Tiểu thuyết gia.": "自訂全站系統字號（小 / 標準 / 大 / 特大），跨頂部列與分頁 5/6 同步；連續簽到 7、21、90、365 天即可解鎖各階小說家勳章。",
    "Mục #5 Chức Năng Linh Tinh & Đa Ngôn Ngữ Toàn Diện": "分頁 6 第 5 雜項趣味欄與全站多語言完整在地化",
    "Khám phá Ô #5 Chức năng linh tinh ở Tab 6, video hướng dẫn tràn khung chuẩn Mobile/Desktop, cùng dịch đầy đủ 6 ngôn ngữ cho mọi thông báo, khung Prompt & ngày giờ bản địa!": "探索分頁 6 第 5 欄雜項趣味功能、適配手機與桌面的滿框影片教學，以及涵蓋全部彈窗提示、主提示詞框架與各地真實日期格式的 6 種語言！",
    "v46.0 — Sửa Repeat/A–B Không Đen Video & Đồng Bộ Nền Chặt (Mod 39/40), Cỡ Chữ Toàn Web, Chuỗi Điểm Danh, Ô #5 Linh Tinh & Video Tràn Khung Mobile": "v46.0 — 修復循環/A–B 黑畫面與緊密背景同步 (Mod 39/40)、全域字號、連續簽到勳章、第 5 雜項欄與行動端滿框影片",
    "Sửa triệt để YouTube Repeat/A–B & Đồng bộ Video Nền (Mod 39/40 + nativePlayer): Không phá hủy hay làm đen iframe khi bật Lặp toàn video / A–B; Video nền đồng bộ tức thì Tạm dừng / Phát / Tua theo cả iframe lẫn luồng HTML5 trực tiếp.": "徹底修復 YouTube 循環/A–B 與背景影片同步問題（Mod 39/40 + nativePlayer）：開啟整片循環或 A–B 循環時不再銷毀或黑屏 iframe；網頁背景影片即時跟隨主畫面 iframe 及直連串流同步暫停/播放/拖曳。",
    "Video Hướng Dẫn Hiển Thị Trọn Khung Trên Mobile & Fullscreen (Mod 28 + Mod 33): Gỡ triệt để lỗi co góc trên-trái trên điện thoại dọc & cập nhật thêm Phân đoạn #21 (~10:22) bao phủ mọi tính năng mới.": "教學影片在手機端與全螢幕模式完整鋪滿畫框（Mod 28 + Mod 33）：徹底解決直式手機畫面縮在左上角的問題，並新增第 21 節（~10:22）全面講解新功能。",
    "Cỡ Chữ Toàn Trang 4 Mức (Nhỏ -> Rất to), Mốc Huy Hiệu Điểm Danh (7/21/90/365 ngày) & Ô #5 Chức Năng Linh Tinh tại Tab 6 tối ưu responsive trên mọi kích thước màn hình.": "全站 4 檔字號調節（小 -> 特大）、連續簽到里程碑勳章（7/21/90/365 天）以及分頁 6 第 5 趣味欄全尺寸響應式適配。",
    "Hoàn Thiện Đa Ngôn Ngữ 6 Thứ Tiếng (EN / 简体 / 繁體 / KO / JA / VI): Bao gồm cả Prompt Khung 5 Chế độ, thông báo góc thu/mở, thẻ trạng thái & định dạng ngày giờ thực tế từng quốc gia (YY/MM/DD, MM/DD/YY, dd/mm/yy).": "完善 6 種語言全站在地化（EN / 簡中 / 繁中 / KO / JA / VI）：涵蓋全部 5 大模式主提示詞框架、收合/展開角標提示、狀態卡片以及各國真實日期格式（YY/MM/DD、MM/DD/YY、dd/mm/yy）。",
