    "Server Cloudflare Worker / Piped riêng (khuyên dùng trên điện thoại để bật PiP & nghe tắt màn hình 100%):": "自訂 Cloudflare Worker / Piped 伺服器（手機端推薦，100% 支援子母畫面與關螢幕聽音）：",
    "https://yt-stream-proxy.ten-cua-ban.workers.dev": "https://yt-stream-proxy.your-name.workers.dev",
    "💡 Mẹo bật PiP & Nghe Nền 100% trên Điện thoại (GitHub Pages là web tĩnh): Do YouTube chặn IP các server Piped/Invidious công cộng, bạn chỉ cần tạo 1 Cloudflare Worker miễn phí (100.000 lượt/ngày), dán đoạn code mẫu vào là trình phát chuyển sang video HTML5 gốc — thoát trình duyệt tự thu nhỏ PiP và khóa màn hình vẫn nghe mượt!": "💡 手機端 100% 子母畫面與背景播放技巧（GitHub Pages 為靜態網站）：由於 YouTube 封鎖公開 Piped/Invidious 伺服器 IP，只需建立免費的 Cloudflare Worker（每日 10 萬次請求）並貼上範本程式碼，播放器即可升級為原生 HTML5 影片——離開瀏覽器自動縮小、鎖定螢幕也能流暢聽音！",
