    "📺 Đã bật khung Video Hình Tab 5 đồng bộ với Âm thanh nền Tab 3!": "📺 已開啟分頁 5 影片畫面並與第 3 節背景音訊即時同步！",
    "🎧 Video này chỉ lấy được luồng audio — đang phát nền qua Tab 3.": "🎧 此影片僅取得音訊流 — 正在透過第 3 節背景播放。",
    "🎧 Đã ẩn khung hình để tiết kiệm pin/dữ liệu — Tab 3 MP3 Audio vẫn phát liên tục.": "🎧 已隱藏畫面以省電/省流量 — 第 3 節 MP3 音訊持續不間斷播放。",
    "⏹️ Tắt MP3": "⏹️ 停止 MP3",
    "⏹️ Tắt Video": "⏹️ 關閉影片",
