    "⏹️ Đã dừng hẳn và tắt trình phát MP3.": "⏹️ 已停止並關閉 MP3 播放器。",
    "⏹️ Đã dừng và tắt hẳn trình phát Video YouTube.": "⏹️ 已停止並關閉 YouTube 影片播放器。",
    "🎬 Bạn đang xem video YouTube": "🎬 正在觀看 YouTube 影片",
    "Bạn đang xem video YouTube. Bạn có muốn tắt video YouTube để nghe tệp nhạc này không?": "您目前正在觀看 YouTube 影片。是否關閉 YouTube 影片以收聽此音樂檔案？",
    "Tệp nhạc đã chọn:": "已選音樂檔案：",
