    "🎬 CHỈ THỊ HỢP NHẤT CHẾ ĐỘ 1 × STORY BIBLE × MỐC PHÂN CẢNH / POV": "🎬 模式 1 × 故事聖經 × 分鏡節點 / POV 整合指令",
