    "🧭 DIỄN BIẾN & DÀN Ý CỐT TRUYỆN ĐÃ PHÁT TRIỂN Ở CHẾ ĐỘ 2 (LỒNG GHÉP SÂU)": "🧭 模式 2 已深化的劇情脈絡與大綱（深度融合）",
    "Hãy lồng ghép khéo léo và triển khai chậm rãi, giàu chiều sâu tâm lý theo diễn biến cốt truyện từ Chế độ 2 dưới đây kết hợp hài hòa với Story Bible, Mốc chuyển phân cảnh và Câu lệnh bên dưới (tuyệt đối không tua nhanh sự kiện):": "請結合故事聖經、分鏡節點及下文作者指令，巧妙融入並緩慢紮實展開以下模式 2 劇情構思，注重心理刻畫（嚴禁快進省略事件）：",
