    "Đánh giá theo góc nhìn độc giả beta, chấm điểm nhịp điệu và chỉ ra các đoạn sáo rỗng cần sửa theo kỹ thuật Show Don't Tell.": "從 Beta 讀者視角進行評價，為節奏評分，並指出需按「展示而非告知」技法改寫的套話段落。",
